import{_ as r,o as d,c as o,a2 as n}from"./chunks/framework.CjPXnAcb.js";const b=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表"},"headers":[],"relativePath":"glossary/index.md","filePath":"glossary/index.md"}'),s={name:"glossary/index.md"};function e(a,t,g,i,l,c){return d(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><blockquote><p>站规：任何术语第一次出现，必须用一句大白话解释，并收进这张表。查词先来这里。</p></blockquote><h2 id="工具与版本控制" tabindex="-1">工具与版本控制 <a class="header-anchor" href="#工具与版本控制" aria-label="Permalink to &quot;工具与版本控制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>大白话解释</th></tr></thead><tbody><tr><td><strong>命令行</strong></td><td>用打字的方式给电脑下指令的界面（那个黑窗口），开发者的主要工作方式</td></tr><tr><td><strong>工作目录</strong></td><td>命令行里你当前「站」在哪个文件夹；相对路径都从这里算起</td></tr><tr><td><strong>环境变量</strong></td><td>操作系统层面的全局设置，像电脑的「公共便签」，程序都能读到</td></tr><tr><td><strong>PATH</strong></td><td>一个特殊的环境变量：记录「去哪些文件夹找程序」的地址簿；找不到就报「不是内部或外部命令」</td></tr><tr><td><strong>便携版</strong></td><td>解压即用、不写注册表的软件形态，可以放在任何文件夹（所以常要手动加 PATH）</td></tr><tr><td><strong>Git</strong></td><td>版本控制工具：给文件夹拍快照的「时光机」，任何时刻可回看、可回滚</td></tr><tr><td><strong>GitHub</strong></td><td>托管 Git 仓库的网站，程序员的「云端仓库 + 社交平台」</td></tr><tr><td><strong>仓库</strong>（Repository / repo）</td><td>被 Git 管理的项目文件夹，连同它的全部历史快照</td></tr><tr><td><strong>暂存</strong>（add）</td><td>挑选哪些改动要进入下一次快照</td></tr><tr><td><strong>提交</strong>（commit）</td><td>把暂存好的改动拍成一张快照，并附一句说明</td></tr><tr><td><strong>推送</strong>（push）</td><td>把本地的新快照上传到云端仓库（如 GitHub）</td></tr><tr><td><strong>克隆</strong>（clone）</td><td>把云端仓库完整复制到本地</td></tr><tr><td><strong>分支</strong>（branch）</td><td>平行的开发线，各改各的互不干扰，之后可合并（本站固定用 <code>main</code> 主分支）</td></tr><tr><td><strong>token</strong>（令牌）</td><td>访问 GitHub 等服务的「门禁卡」，卡上刻着权限范围（scope）；要像密码一样保密</td></tr><tr><td><strong>YAML</strong></td><td>用缩进表示层级的配置文件格式，GitHub Actions 的工作流就用它写</td></tr></tbody></table><h2 id="建站与部署" tabindex="-1">建站与部署 <a class="header-anchor" href="#建站与部署" aria-label="Permalink to &quot;建站与部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>大白话解释</th></tr></thead><tbody><tr><td><strong>Node.js</strong></td><td>让 JavaScript 脱离浏览器、在电脑上独立运行的「舞台」</td></tr><tr><td><strong>npm</strong></td><td>JavaScript 的包管理器：应用商店 + 快递员</td></tr><tr><td><strong>依赖</strong>（dependency）</td><td>项目里用到的别人写好的代码包</td></tr><tr><td><strong>package.json</strong></td><td>项目的「采购清单 + 说明书」，npm 靠它知道装什么、怎么跑</td></tr><tr><td><strong>镜像</strong></td><td>官方下载仓库的国内「分店」，物理距离近所以快（如 npmmirror、清华 pip 源）</td></tr><tr><td><strong>VitePress</strong></td><td>静态网站生成器：把一堆 Markdown 文件变成带导航和搜索的漂亮网站</td></tr><tr><td><strong>Markdown</strong></td><td>用纯文本符号（<code>#</code>、<code>**</code>）写排版的标记语言，本站每一页都是它</td></tr><tr><td><strong>frontmatter</strong></td><td>文件开头两条 <code>---</code> 之间的小块元信息（如标题、布局），给程序看的不正文</td></tr><tr><td><strong>静态网站</strong></td><td>服务器只发现成文件、不做现场计算的网站——快、稳、免费托管</td></tr><tr><td><strong>部署</strong>（deploy）</td><td>把网站或程序放到线上，让别人能访问</td></tr><tr><td><strong>GitHub Pages</strong></td><td>GitHub 免费的静态网站托管服务，本站就住在这里</td></tr><tr><td><strong>GitHub Actions</strong></td><td>GitHub 的自动化流水线：代码一推送，自动跑构建、部署等脚本</td></tr><tr><td><strong>CI/CD</strong></td><td>持续集成 / 持续交付的统称：推送代码后自动构建、检查、上线的工程实践</td></tr></tbody></table><h2 id="网络与-api" tabindex="-1">网络与 API <a class="header-anchor" href="#网络与-api" aria-label="Permalink to &quot;网络与 API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>大白话解释</th></tr></thead><tbody><tr><td><strong>HTTP</strong></td><td>浏览器/程序与服务器之间沟通的协议，一对「点菜语言」</td></tr><tr><td><strong>HTTPS</strong></td><td>加密版的 HTTP，内容在路上不被偷看</td></tr><tr><td><strong>URL</strong></td><td>网址：协议 + 服务器地址 + 路径</td></tr><tr><td><strong>GET / POST</strong></td><td>HTTP 的两个常用动作：GET 取数据（看菜单），POST 交数据（下单）</td></tr><tr><td><strong>状态码</strong></td><td>服务器回话的数字暗号：200 成功、404 没这页、401 没权限、500 服务器出错</td></tr><tr><td><strong>JSON</strong></td><td>程序之间传数据的标准格式，<code>&quot;键&quot;: 值</code> 的写法</td></tr><tr><td><strong>API</strong></td><td>程序对程序开放的「服务窗口」，按约定格式发请求、拿响应</td></tr><tr><td><strong>API Key</strong></td><td>调 API 的身份凭证（会员卡号），证明你是谁、给你记账；<strong>要保密</strong></td></tr></tbody></table><h2 id="大模型-llm" tabindex="-1">大模型（LLM） <a class="header-anchor" href="#大模型-llm" aria-label="Permalink to &quot;大模型（LLM）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>大白话解释</th></tr></thead><tbody><tr><td><strong>LLM</strong>（大语言模型）</td><td>读过海量文本、会续写会对话的 AI 模型，如 GLM、GPT</td></tr><tr><td><strong>Prompt</strong>（提示词）</td><td>发给模型的指令或问题；怎么问，很大程度决定答得怎么样</td></tr><tr><td><strong>Token</strong>（词元）</td><td>模型处理文字的最小单位（约 1 个汉字 = 1~2 个 token），也是计费和限长单位</td></tr><tr><td><strong>上下文</strong>（context）</td><td>一次请求里模型能「看到」的全部内容，有长度上限，超了就记不住</td></tr><tr><td><strong>流式输出</strong></td><td>回答一边生成一边一段段传回来，而不是憋到最后一次性给</td></tr><tr><td><strong>多轮对话</strong></td><td>把之前的聊天记录一起发过去，让模型「记得」聊过什么</td></tr><tr><td><strong>幻觉</strong>（hallucination）</td><td>模型一本正经地编造不存在的事实</td></tr><tr><td><strong>Embedding</strong>（向量嵌入）</td><td>把文字变成一串数字（向量），意思越近的文字，向量越「近」</td></tr><tr><td><strong>RAG</strong>（检索增强生成）</td><td>先去资料库检索相关段落，再塞给模型让它「看着资料回答」</td></tr><tr><td><strong>Agent</strong>（智能体）</td><td>能自主决定「调哪个工具、下一步做什么」的 AI 程序</td></tr><tr><td><strong>Function Calling</strong>（函数调用）</td><td>让模型按约定格式请求调用外部工具（查天气、算数、搜索）的机制</td></tr><tr><td><strong>微调</strong>（fine-tuning）</td><td>用自己的数据继续训练模型，改的是模型本身</td></tr><tr><td><strong>推理</strong>（inference）</td><td>用训练好的模型生成回答的过程（对应「训练」）</td></tr></tbody></table><hr><div class="warning custom-block"><p class="custom-block-title">维护规则</p><p>按站规，每次学到新术语，学完当天就把它加进对应分组；解释不超过一句话，看不懂就改到看得懂为止。</p></div>',12)])])}const p=r(s,[["render",e]]);export{b as __pageData,p as default};
